using System;using System.IO;using System.Linq;using System.Text.Json;using System.Text.Json.Serialization;using Spacewars.Runtime;using Spacewars.Simulation;
class Export {static void Main(string[] args){var b=new NavigationRetentionBudget();NavigationArrivalWork work=null;try {if(!b.TryOpenScope(NavigationPreparationKind.Decode,7,0,out var scope))throw new Exception("scope");using(scope){using var r=new BinaryReader(File.OpenRead(File.ReadAllText(Path.Combine(args[0],"donor-path.txt"))));work=(NavigationArrivalWork)NavPhysicalBodyWire.ReadFrom(r,scope.OwnedReservation());scope.Attach(work);scope.Commit(work,_=>{});}var rows=work.PhysicalInput.WorkingBindings.Select(binding=>{var p=(PartitionNavigationProvider)binding.Provider;var g=(TerrainLocations)typeof(PartitionNavigationProvider).GetField("locations",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(p);var f=binding.Profile;return new {binding.Entity,p.Binding,p.HoldBinding,g.Geometry.Revision,g.Geometry.HalfExtent,profile=new{f.ExactProfileBinding,f.CostId,f.CostRevision,f.GridCell},obstacles=g.Geometry.Obstacles.Select(o=>new{o.MinX,o.MinZ,o.MaxX,o.MaxZ,o.CircleRadius,o.Bottom,o.Top,polygon=o.Polygon?.Vertices.Select(v=>new{v.X,v.Z}).ToArray()}).ToArray()};}).ToArray();File.WriteAllText(Path.Combine(args[0],"declarations.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true,NumberHandling=JsonNumberHandling.AllowNamedFloatingPointLiterals}));}finally{work?.ReleaseOwner();if(b.PhysicalBytes!=0||b.HeldBytes!=0||b.ActiveScopes!=0)throw new Exception("ledger");}}}
